INSERT INTO `quotations` VALUES ('c80b5260-9064-4720-97b9-78fa764d41b3','张美玲','阀体WCB，闸板304，单向硬密封。硬密封不做试压会有一定的漏水；连接方式：对夹PN10，执行方式气动含双左右气缸+限位开关+两位五通电磁阀+过滤器。此价格含税不含运费','预定定金30%，付清余款发货。','木箱包装。可以提供产品使用说明，产品材质报告，产品检测报告。','童惠业','13957713583','15天',0.00,'draft','2026-06-05 22:39:48',NULL);
